void rc_DrawBanner(void)
{
    char    buf[24];
    int16_t n;

    Graphics_FillRect(50, 84, SCREEN_W - 51, 140, C_BLACK);
    Graphics_FillRect(50, 84, SCREEN_W - 51, 85, C_GOLD);
    Graphics_FillRect(50, 139, SCREEN_W - 51, 140, C_GOLD);

    if(rc_banner == BAN_CLEAR)
    {
        rc_DrawText("ROOM CLEARED!", SCREEN_W / 2, 105, C_GREEN);
        rc_DrawText("Find the glowing door", SCREEN_W / 2, 126, C_GRAY);
    }
    else if(rc_lv.boss)
    {
        rc_DrawText("DRAGON ROUND", SCREEN_W / 2, 105, C_RED);
        rc_DrawText("Find the Dragon Den", SCREEN_W / 2, 126, C_GRAY);
    }
    else
    {
        n  = rc_Cat(buf, 0, "ROUND ", 6);
        n += rc_Itoa(buf + n, rc_level + 1);
        rc_DrawText(buf, SCREEN_W / 2, 105, C_WHITE);
        rc_DrawText("Buy doors with BLUE", SCREEN_W / 2, 126, C_GRAY);
    }
}


void rc_DrawEndScreen(void)
{
    char    buf[28];
    int16_t n;

    Graphics_FillRect(0, 0, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);

    rc_DrawText("GAME OVER", SCREEN_W / 2, 55, C_RED);
    n  = rc_Cat(buf, 0, "Died in round ", 14);
    rc_Itoa(buf + n, rc_level + 1);
    rc_DrawText(buf, SCREEN_W / 2, 90, C_WHITE);

    n  = rc_Cat(buf, 0, "Level ", 6);
    rc_Itoa(buf + n, rc_xpLv);
    rc_DrawText(buf, SCREEN_W / 2, 120, C_XP);

    n  = rc_Cat(buf, 0, "Kills ", 6);
    rc_Itoa(buf + n, rc_kills);
    rc_DrawText(buf, SCREEN_W / 2, 148, C_GRAY);

    n  = rc_Cat(buf, 0, "Gold ", 5);
    rc_Itoa(buf + n, rc_gold);
    rc_DrawText(buf, SCREEN_W / 2, 174, C_GOLD);

    {
        static const UiHint k[] = { { UI_ICON_SELECT, "Exit" } };
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 222, C_BLACK);
    }
}


// Returns: 0 = can buy, 1 = can't afford, 2 = unavailable (owned / maxed / full).
// Fills the short status text ("90g", "OWNED", "MAX"...) and the price.
static uint16_t OfferState(uint16_t off, char *stat, uint16_t *costOut)
{
    const Offer *of = &rc_kOffer[off];
    uint16_t cost = 0, lv = 0, mx = 0;
    int16_t  n;

    stat[0]  = 0;
    *costOut = 0;

    if(of->kind == K_STAT)
    {
        switch(of->idx)
        {
            case ST_DMG:   lv = rc_lvDmg;   mx = 6; cost = 30 + 25 * lv; break;
            case ST_RATE:  lv = rc_lvRate;  mx = 5; cost = 30 + 25 * lv; break;
            case ST_SPEED: lv = rc_lvSpeed; mx = 4; cost = 25 + 20 * lv; break;
            case ST_GOLD:  lv = rc_lvGold;  mx = 4; cost = 40 + 30 * lv; break;
            case ST_HEART:
                lv = rc_maxHp - RC_START_HEARTS;
                mx = RC_MAX_HEARTS - RC_START_HEARTS;
                cost = 70 + 50 * lv;
                break;
            default:                                            // ST_HEAL
                if(rc_hp >= rc_maxHp) { rc_Cat(stat, 0, "FULL", 4); return 2; }
                cost = 20;
                n = rc_Itoa(stat, cost);
                rc_Cat(stat, n, "g", 1);
                *costOut = cost;
                return (rc_gold >= cost) ? 0 : 1;
        }

        if(lv >= mx) { rc_Cat(stat, 0, "MAX", 3); return 2; }
    }
    else if(of->kind == K_TRAIT)
    {
        if(rc_traits & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kTraitCost[of->idx];
    }
    else if(of->kind == K_STAFF)
    {
        if(rc_staffOwned & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kStaffCost[of->idx];
    }
    else
    {
        if(rc_itemOwned & (1u << of->idx)) { rc_Cat(stat, 0, "OWNED", 5); return 2; }
        cost = rc_kItemCost[of->idx];
    }

    n = rc_Itoa(stat, cost);
    rc_Cat(stat, n, "g", 1);
    *costOut = cost;
    return (rc_gold >= cost) ? 0 : 1;
}


// Three distinct random offers from whatever is still available.
static void RollCards(void)
{
    uint16_t pool[NUM_OFFER], n = 0, i, k, cost;
    char     stat[16];

    for(i = 0; i < NUM_OFFER; i++)
        if(OfferState(i, stat, &cost) != 2) pool[n++] = i;

    for(i = 0; i < 3; i++)
    {
        if(n == 0)
        {
            rc_card[i].off  = CARD_NONE;
            rc_card[i].sold = 1;
            continue;
        }
        k = Rand16() % n;
        rc_card[i].off  = pool[k];
        rc_card[i].sold = 0;
        pool[k] = pool[--n];
    }
    rc_cardDirty = CD_ALL;
}


static uint16_t RerollCost(void)
{
    return (uint16_t)(15u + 10u * rc_rerolls);
}


static void DrawCard(uint16_t i)
{
    int16_t  x0 = (int16_t)(CARD_X0 + (int16_t)i * (CARD_W + CARD_GAP));
    int16_t  y0 = CARD_Y0;
    int16_t  x1 = (int16_t)(x0 + CARD_W - 1);
    int16_t  y1 = (int16_t)(y0 + CARD_H - 1);
    int16_t  cx = (int16_t)(x0 + CARD_W / 2);
    bool     sel = (rc_cardSel == i);
    uint32_t fill = sel ? COLOR_CHARCOAL : COLOR_TETRIS_GRID;
    uint32_t band;
    const Offer *of;
    const char *kindName;
    char     stat[16], line[16];
    uint16_t st, cost, k, n;
    int16_t  y;

    Graphics_FillRect(x0, y0, x1, y1, sel ? C_CYAN : COLOR_CHARCOAL);       // border
    Graphics_FillRect(x0 + 2, y0 + 2, x1 - 2, y1 - 2, fill);

    if(rc_card[i].off == CARD_NONE)
    {
        rc_DrawSmall("sold out", cx, (int16_t)(y0 + CARD_H / 2), C_DKGRAY, fill);
        return;
    }

    of = &rc_kOffer[rc_card[i].off];
    switch(of->kind)
    {
        case K_STAT:  kindName = "UPGRADE"; band = COLOR_CHARCOAL; break;
        case K_TRAIT: kindName = "TRAIT";   band = COLOR_PURPLE; break;
        case K_STAFF: kindName = "STAFF";   band = COLOR_OLIVE; break;
        default:      kindName = "MAGIC";   band = COLOR_TEAL; break;
    }

    Graphics_FillRect(x0 + 2, y0 + 2, x1 - 2, y0 + 17, band);
    rc_DrawSmall(kindName, cx, (int16_t)(y0 + 10), C_WHITE, band);

    rc_DrawSmall(of->name, cx, (int16_t)(y0 + 32), C_WHITE, fill);

    // Description: lines separated by '|'
    y = (int16_t)(y0 + 54);
    n = 0;
    for(k = 0; ; k++)
    {
        char ch = of->desc[k];

        if(ch == '|' || ch == 0)
        {
            line[n] = 0;
            rc_DrawSmall(line, cx, y, C_GRAY, fill);
            y = (int16_t)(y + 15);
            n = 0;
            if(ch == 0) break;
        }
        else if(n < 14)
            line[n++] = ch;
    }

    // Price / state
    if(rc_card[i].sold)
    {
        rc_DrawText("SOLD", cx, (int16_t)(y1 - 16), C_DKGRAY);
    }
    else
    {
        st  = OfferState(rc_card[i].off, stat, &cost);
        rc_DrawTextEx(stat, cx, (int16_t)(y1 - 16),
                   (st == 0) ? C_GREEN : (st == 1) ? C_BAD : C_GRAY, fill, false);
    }
}


static void DrawReroll(void)
{
    char     buf[16];
    int16_t  n;
    bool     sel = (rc_cardSel == 3);
    uint32_t fill = sel ? COLOR_CHARCOAL : COLOR_TETRIS_GRID;
    uint16_t cost = RerollCost();

    Graphics_FillRect(RR_X0, RR_Y0, RR_X1, RR_Y1, sel ? C_CYAN : COLOR_CHARCOAL);
    Graphics_FillRect(RR_X0 + 2, RR_Y0 + 2, RR_X1 - 2, RR_Y1 - 2, fill);

    n  = rc_Cat(buf, 0, "REROLL  ", 8);
    n += rc_Itoa(buf + n, cost);
    rc_Cat(buf, n, "g", 1);
    rc_DrawTextEx(buf, (RR_X0 + RR_X1) / 2, (RR_Y0 + RR_Y1) / 2,
               (rc_gold >= cost) ? C_WHITE : C_BAD, fill, false);
}


static void DrawCardsGold(void)
{
    char    buf[16];
    int16_t n;

    Graphics_FillRect(190, 2, SCREEN_W - 1, 28, C_BLACK);
    n = rc_Cat(buf, 0, "G ", 2);
    rc_Itoa(buf + n, rc_gold);
    rc_DrawText(buf, 275, 15, C_GOLD);
}


static void DrawCardMsg(void)
{
    Graphics_FillRect(172, RR_Y0, SCREEN_W - 1, RR_Y1, C_BLACK);
    rc_DrawText(rc_kMsgText[rc_cardMsg], 245, (RR_Y0 + RR_Y1) / 2,
             (rc_cardMsg == 1 || rc_cardMsg == 4) ? C_GREEN : C_BAD);
}


void rc_DrawCardsFull(void)
{
    char    buf[24];
    int16_t n;

    Graphics_FillRect(0, 0, SCREEN_W - 1, SCREEN_H - 1, C_BLACK);

    n  = rc_Cat(buf, 0, "LEVEL UP!  Lv ", 14);
    n += rc_Itoa(buf + n, rc_xpLv);
    rc_DrawText(buf, 105, 15, C_XP);
    if(rc_lvPending > 1)
    {
        n  = rc_Cat(buf, 0, "x", 1);
        rc_Itoa(buf + n, rc_lvPending);
        rc_DrawSmall(buf, 215, 15, C_GRAY, C_BLACK);
    }

    Graphics_setForegroundColor(&g_sContext, C_GRAY);
    Graphics_drawLine(&g_sContext, 10, 30, SCREEN_W - 11, 30);
    {
        static const UiHint k[] =
        {
            { UI_ICON_MOVE,   "Pick"     },
            { UI_ICON_SELECT, "Buy"      },
            { UI_ICON_BACK,   "Continue" }
        };
        Ui_DrawHints(k, UI_ARRAY_LEN(k), 228, C_BLACK);
    }
    rc_cardDirty = CD_ALL;
}


void rc_CardsRender(void)
{
    uint16_t i;

    for(i = 0; i < 3; i++)
        if(rc_cardDirty & (1u << i)) DrawCard(i);
    if(rc_cardDirty & CD_REROLL) DrawReroll();
    if(rc_cardDirty & CD_GOLD)   DrawCardsGold();
    if(rc_cardDirty & CD_MSG)    DrawCardMsg();

    rc_cardDirty = 0;
}


void rc_EnterCards(void)
{
    rc_mode      = MODE_CARDS;
    rc_dirtyFull = true;
    rc_cardSel   = 1;
    rc_cardMsg   = 0;
    rc_rerolls   = 0;
    rc_stX = rc_stY = 1;                  // ignore a stick that is already pushed
    RollCards();
    rc_Sfx(&sfx_level_up);
}


static void BuyCard(uint16_t i)
{
    const Offer *of;
    char         stat[16];
    uint16_t     cost, st;

    rc_cardDirty |= CD_MSG;

    if(rc_card[i].off == CARD_NONE || rc_card[i].sold)
    {
        rc_cardMsg = 3;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    of = &rc_kOffer[rc_card[i].off];
    st = OfferState(rc_card[i].off, stat, &cost);

    if(st == 2)         { rc_cardMsg = 3; rc_Sfx(&sfx_menu_bump); return; }
    if(rc_gold < cost)   { rc_cardMsg = 2; rc_Sfx(&sfx_menu_bump); return; }

    rc_gold -= cost;

    switch(of->kind)
    {
        case K_STAT:
            switch(of->idx)
            {
                case ST_DMG:   rc_lvDmg++;   break;
                case ST_RATE:  rc_lvRate++;  break;
                case ST_SPEED: rc_lvSpeed++; break;
                case ST_GOLD:  rc_lvGold++;  break;
                case ST_HEART: rc_maxHp++; rc_hp++; break;
                default:       rc_hp++;      break;              // heal
            }
            break;

        case K_TRAIT:
            rc_traits |= (1u << of->idx);
            break;

        case K_STAFF:
            rc_staffOwned |= (1u << of->idx);
            rc_equip       = of->idx;
            break;

        default:                                                // K_ITEM
            rc_itemOwned |= (1u << of->idx);
            rc_equip      = NUM_STAFF + of->idx;
            break;
    }

    rc_card[i].sold = 1;
    rc_cardMsg      = 1;
    rc_cardDirty   |= CD_GOLD | CD_REROLL | 0x07;                // prices may now be affordable / not
    rc_Sfx(&sfx_coin);
}


static void RerollCards(void)
{
    uint16_t cost = RerollCost();

    rc_cardDirty |= CD_MSG;

    if(rc_gold < cost)
    {
        rc_cardMsg = 2;
        rc_Sfx(&sfx_menu_bump);
        return;
    }

    rc_gold -= cost;
    rc_rerolls++;
    RollCards();
    rc_cardMsg    = 4;
    rc_cardDirty |= CD_GOLD | CD_REROLL | CD_MSG;
    rc_Sfx(&sfx_menu_select);
}


static void LeaveCards(void)
{
    rc_Sfx(&sfx_menu_back);

    if(rc_lvPending) rc_lvPending--;

    if(rc_lvPending > 0)                 // more level-ups waiting: next set of cards
    {
        rc_rerolls   = 0;
        rc_cardMsg   = 0;
        rc_cardSel   = 1;
        rc_dirtyFull = true;
        RollCards();
    }
    else
    {
        rc_mode      = MODE_PLAY;
        rc_dirtyFull = true;
    }
}


void rc_UpdateCards(void)
{
    int16_t  sx = rc_StickEdge(g_joy.dx, &rc_stX);
    uint16_t old = rc_cardSel;

    (void)rc_StickEdge(g_joy.dy, &rc_stY);

    if(Ui_Back()) { LeaveCards(); return; }          // RED = continue / leave

    if(sx < 0)                                       // MOVE = the stick
        rc_cardSel = (rc_cardSel + 3u) % 4u;
    else if(sx > 0)
        rc_cardSel = (rc_cardSel + 1u) % 4u;

    if(rc_cardSel != old)
    {
        rc_cardDirty |= (old == 3 ? CD_REROLL : (1u << old)) |
                       (rc_cardSel == 3 ? CD_REROLL : (1u << rc_cardSel));
        rc_Sfx(&sfx_menu_move);
    }

    if(Ui_Select())                                  // BLUE / stick click = buy
    {
        if(rc_cardSel < 3) BuyCard(rc_cardSel);
        else              RerollCards();
    }
}
